const urls = [
  "https://wiki.homelab.local/forgejo/backup-design",
  "https://forgejo.org/docs/latest/admin/command-line/"
];
const out = [];
for (const u of urls) {
  try {
    const r = await fetch(u, { redirect: "follow" });
    const t = await r.text();
    out.push({ url: u, status: r.status, len: t.length, head: t.slice(0, 1500) });
  } catch (e) {
    out.push({ url: u, error: String(e) });
  }
}
return out;

