const r = await fetch("https://forgejo.org/docs/latest/admin/command-line/", { redirect: "follow" });
let t = await r.text();
// strip tags crudely
const text = t.replace(/<script[\s\S]*?<\/script>/g, " ").replace(/<style[\s\S]*?<\/style>/g, " ").replace(/<[^>]+>/g, " ").replace(/&quot;/g,'"').replace(/&amp;/g,"&").replace(/&#39;/g,"'").replace(/&gt;/g,">").replace(/&lt;/g,"<").replace(/\s+/g, " ");
const idx = text.toLowerCase().indexOf("dump");
const hits = [];
const re = /dump/gi; let m;
while ((m = re.exec(text)) !== null) { hits.push(m.index); if (hits.length > 6) break; }
return { idx, snippets: hits.map(i => text.slice(Math.max(0,i-200), i+900)) };

